function trcParse(text){
  var arr;
  try{ arr=JSON.parse(String(text||'')); }catch(e){ return { error:'JSON 解析失败：'+e.message }; }
  if(!Array.isArray(arr) || !arr.length) return { error:'需要非空 span 数组' };
  var spans=[], names={};
  for(var i=0;i<arr.length;i++){
    var s=arr[i];
    if(!s || typeof s.name!=='string' || !s.name) return { error:'第 '+(i+1)+' 个 span 缺少 name' };
    var start=Number(s.start), dur=Number(s.dur);
    if(!isFinite(start)||start<0) return { error:'span "'+s.name+'" start 非法' };
    if(!isFinite(dur)||dur<=0) return { error:'span "'+s.name+'" dur 非法' };
    if(names[s.name]) return { error:'span name 重复："'+s.name+'"' };
    names[s.name]=1;
    spans.push({ name:s.name, start:start, dur:dur, parent:(typeof s.parent==='string'&&s.parent)?s.parent:null });
  }
  for(i=0;i<spans.length;i++) if(spans[i].parent && !names[spans[i].parent]) return { error:'span "'+spans[i].name+'" 的 parent 不存在' };
  return { error:null, spans:spans };
}
function trcDepth(spans){
  var byName={}, i;
  for(i=0;i<spans.length;i++) byName[spans[i].name]=spans[i];
  var depth={};
  function d(s, guard){
    if(guard>spans.length) return -1;
    if(!s.parent) return 0;
    var pd=d(byName[s.parent], guard+1);
    return pd<0 ? -1 : pd+1;
  }
  for(i=0;i<spans.length;i++){
    var dd=d(spans[i],0);
    if(dd<0) return { error:'parent 链存在环' };
    depth[spans[i].name]=dd;
  }
  return { error:null, depth:depth };
}
function trcStats(spans){
  var end=0, slow=spans[0], i;
  for(i=0;i<spans.length;i++){
    end=Math.max(end, spans[i].start+spans[i].dur);
    if(spans[i].dur>slow.dur) slow=spans[i];
  }
  return { total:end, slowest:slow.name, slowestDur:slow.dur };
}
function trcEsc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function trcSvg(spans){
  var D=trcDepth(spans);
  if(D.error) return '';
  var st=trcStats(spans);
  var ROW=28, LBL=180, CHART=560, PAD=10;
  var W=LBL+CHART+PAD*2, H=PAD*2+spans.length*ROW+18;
  var cols=['#5E6AD2','#22D3EE','#10B981','#A78BFA','#F5A623'];
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  for(var g=0;g<=4;g++){
    var gx=LBL+PAD+CHART*g/4;
    s+='<line x1="'+gx+'" y1="'+PAD+'" x2="'+gx+'" y2="'+(H-18)+'" stroke="rgba(255,255,255,.06)"/>';
    s+='<text x="'+gx+'" y="'+(H-4)+'" font-family="system-ui,sans-serif" font-size="10" fill="#71717A" text-anchor="middle">'+Math.round(st.total*g/4)+'ms</text>';
  }
  for(var i=0;i<spans.length;i++){
    var sp=spans[i], y=PAD+i*ROW, dep=D.depth[sp.name];
    var x=LBL+PAD+CHART*sp.start/st.total, w=Math.max(2, CHART*sp.dur/st.total);
    var c = sp.name===st.slowest ? '#EF4444' : cols[dep%cols.length];
    s+='<text x="'+(PAD+dep*14)+'" y="'+(y+ROW/2+4)+'" font-family="system-ui,sans-serif" font-size="12" fill="#A1A1AA">'+trcEsc(sp.name)+'</text>';
    s+='<rect x="'+x+'" y="'+(y+5)+'" width="'+w+'" height="'+(ROW-12)+'" rx="4" fill="'+c+'" opacity="0.85"/>';
    s+='<text x="'+Math.min(W-PAD-30, x+w+6)+'" y="'+(y+ROW/2+4)+'" font-family="system-ui,sans-serif" font-size="10" fill="#71717A">'+sp.dur+'ms</text>';
  }
  return s+'</svg>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { trcParse:trcParse, trcDepth:trcDepth, trcStats:trcStats, trcSvg:trcSvg, trcEsc:trcEsc };
}
if (typeof window !== 'undefined') {
  window.TraceForgePure = { trcParse:trcParse, trcDepth:trcDepth, trcStats:trcStats, trcSvg:trcSvg, trcEsc:trcEsc };
}
